      ],
      "consultas": [
        "Há trechos sobre testes periódicos, prova funcional, bypass, manutenção ou indisponibilidade de intertravamentos em bombas de hidrocarbonetos?",
        "Existem trechos sobre inspeção, calibração, falhas de demanda ou gestão de manutenção de PSVs usadas como única barreira física a jusante?"
      ]
    },
    {
      "relacao": "Efeito de roll, pitch, trim e acúmulo de líquidos sobre contrapressão, slugging e desempenho do sistema de flare em FPSO",
      "recorte_destino": "F03",
